# Builds b0_stageC2.py from b0_stageC.py: same tests, plus a memo shared by all the H of one pair (tau, F).
# The three local tests of stage C (nb1, forced, nb2) are run on the vertex sets L0 + vs + {w, sigma w}, L0 = S u {p} u A_p,
# vs = {k, tau k} or {k, tau k, k2, tau k2}.  The induced graph depends on H only through the adjacencies of the vertices of
# vs inside L0 + vs (the graph on L0 is the same for all H of the pair (tau, F)).  These adjacencies are put in the memo key,
# so a memo hit returns the result of the identical test.  No test is weakened or skipped.
src = open("b0_stageC.py").read()
def rep(a, b, cnt=1):
    global src
    assert src.count(a) == cnt, (a[:70], src.count(a))
    src = src.replace(a, b)
rep('        for (idx, rows) in Hs:\n', '        GMEMO = {}\n        L0mask = sum(1 << u_ for u_ in L0)\n        for (idx, rows) in Hs:\n')
rep('            nb1_cache = {}; nb2_cache = {}; first_cache = {}\n',
    '            nb1_cache = {}; nb2_cache = {}; first_cache = {}\n'
    '            def gtest(kind, i, j, ks, rw, L):\n'
    '                vs = [X2(q_) for k_ in ks for q_ in (k_, tau[k_])]\n'
    '                msk = L0mask | sum(1 << u_ for u_ in vs)\n'
    '                key = (kind, i, j, tuple(ks), tuple(rows[u_] & msk for u_ in vs), tuple(rows[X2(k_)] & L0mask for k_ in mem))\n'
    '                if key not in GMEMO:\n'
    '                    GMEMO[key] = graph_ok(rw, L)\n'
    '                else:\n'
    '                    TOT["C_memo_hits"] += 1\n'
    '                return GMEMO[key]\n')
rep('                            if graph_ok(rw, L0 + [X2(k), X2(tau[k]), 37, 38]):\n                                good.append(k)\n',
    '                            if gtest("nb1", i, j, (k,), rw, L0 + [X2(k), X2(tau[k]), 37, 38]):\n                                good.append(k)\n')
rep('                            if not graph_ok(rw, L0 + [X2(k), X2(tau[k]), 37, 38]):\n                                fo.append(k)\n',
    '                            if not gtest("fo", i, j, (k,), rw, L0 + [X2(k), X2(tau[k]), 37, 38]):\n                                fo.append(k)\n')
rep('                    rw = rows[:]; wrows(rw, 0, i, j)\n                    add(rw, 37, X2(k)); add(rw, 38, X2(tau[k])); add(rw, 37, X2(k2)); add(rw, 38, X2(tau[k2]))\n                    nb2_cache[key] = graph_ok(rw, L0 + [X2(k), X2(tau[k]), X2(k2), X2(tau[k2]), 37, 38])\n',
    '                    rw = rows[:]; wrows(rw, 0, i, j)\n                    add(rw, 37, X2(k)); add(rw, 38, X2(tau[k])); add(rw, 37, X2(k2)); add(rw, 38, X2(tau[k2]))\n                    ka_, kb_ = min(k, k2), max(k, k2)\n                    nb2_cache[key] = gtest("nb2", i, j, (ka_, kb_), rw, L0 + [X2(ka_), X2(tau[ka_]), X2(kb_), X2(tau[kb_]), 37, 38])\n')
rep('"rej_budget": 0, "rej_psd": 0, "psd_tests": 0, "psd_float_neg_no_cert": 0}', '"rej_budget": 0, "rej_psd": 0, "psd_tests": 0, "psd_float_neg_no_cert": 0, "C_memo_hits": 0}')
# validation mode: explicit list of representatives, separate log prefix
rep('todo = [(idx, e) for idx, e in enumerate(ALLREPS) if idx not in done]\n',
    'todo = [(idx, e) for idx, e in enumerate(ALLREPS) if idx not in done]\nDONEPREFIX = "b0_stageC_done_"\nif os.environ.get("B0_FORCE_IDX"):\n    want = set(int(x_) for x_ in os.environ["B0_FORCE_IDX"].split(","))\n    todo = [(idx, e) for idx, e in enumerate(ALLREPS) if idx in want]\n    DONEPREFIX = "b0_stageCval_"\n')
rep('DONE = open(os.path.join(here, f"b0_stageC_done_{RUNTAG}_{part}of{nparts}.jsonl"), "a")', 'DONE = open(os.path.join(here, f"{DONEPREFIX}{RUNTAG}_{part}of{nparts}.jsonl"), "a")')
src = src.replace('# B0 copy of r3_p250.py, generated by _make_stageC.py: stage C only, on given triples.', '# B0 copy of r3_p250.py, generated by _make_stageC.py then _make_stageC2.py: stage C only, on given triples, with a memo\n# of the local tests shared by the H of one pair (tau, F) (see _make_stageC2.py).', 1)
open("b0_stageC2.py", "w").write(src)
print("written")
